<script setup lang="ts">
import { ref, onUnmounted } from 'vue';
import Vehicles from './Vehicles.vue';
import WorkersPanel from './WorkersPanel.vue';
import WorkerProgress from './WorkerProgress.vue';
type Service={id:number;name:string;active:boolean;mode:string;endpoint:string;wsdl:string;operation:string;auth:string;parameters:Record<string,unknown>;intervalSeconds:number;dataIntervalSeconds:number;emptyIntervalSeconds:number;timeoutSeconds:number};
type Worker={id:number;name:string;idclient:string;user:string;active:boolean;serviceId:number;status:string;nextRun:number;lastRun:number|null;lastSuccess:number|null;failures:number;error:string|null;mark:string;dataIntervalSeconds:number|null;emptyIntervalSeconds:number|null};
type Run={id:number;workerId:number;started:number;finished:number;success:boolean;error:string|null};
const token=ref(''), logged=ref(false), error=ref(''), tab=ref('Przegląd'), busy=ref(false);
const status=ref<{enabled:boolean;capacity:number;running:number;uptime:number;workers:Worker[];services:Service[]}>({enabled:false,capacity:10,running:0,uptime:0,workers:[],services:[]});
const runs=ref<Run[]>([]), payload=ref(''), modal=ref(''), editId=ref<number|null>(null);
const service=ref(newService()), worker=ref(newWorker()), parameters=ref('{}');
const originalWorker=ref<Worker|null>(null);
function newService(){return {name:'',active:true,mode:'trimble',endpoint:'https://soap.box.trimbletl.com/fleet-service/Tracking',wsdl:'',operation:'',auth:'basic',intervalSeconds:60,dataIntervalSeconds:3,emptyIntervalSeconds:180,timeoutSeconds:300};}
function newWorker(){return {name:'',idclient:'',user:'',pass:'',active:true,serviceId:0,mark:'',dataIntervalSeconds:null as number|null,emptyIntervalSeconds:null as number|null};}
async function api(path:string,method='GET',body?:unknown){const r=await fetch('/api'+path,{method,headers:{Authorization:`Bearer ${token.value}`,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)}); if(!r.ok){if(r.status===401)logged.value=false;throw new Error((await r.json()).error??'Błąd połączenia');}return r.status===204?null:r.json();}
async function refresh(){status.value=await api('/status');runs.value=await api('/runs');}
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'Błąd';}finally{busy.value=false;}}
async function login(){await action(async()=>{await refresh();logged.value=true;});}
const timer=setInterval(()=>{if(logged.value&&!busy.value)void refresh().catch(e=>error.value=e.message);},3000);onUnmounted(()=>clearInterval(timer));
function date(v:number|null){return v?new Date(v).toLocaleString('pl-PL'):'—';}
function serviceName(id:number){return status.value.services.find(s=>s.id===id)?.name??'—';}
function openService(s?:Service){editId.value=s?.id??null;service.value=s?{...newService(),...s}:newService();parameters.value=JSON.stringify(s?.parameters??{idclient:'{{idclient}}',user:'{{user}}',pass:'{{pass}}'},null,2);modal.value='service';}
function openWorker(w?:Worker){originalWorker.value=w?{...w}:null;editId.value=w?.id??null;worker.value=w?{...w,pass:''}:{...newWorker(),serviceId:status.value.services[0]?.id??0};modal.value='worker';}
function pauseValue(value:unknown){return value===''||value==null?null:Number(value);}
async function save(){await action(async()=>{const previous=originalWorker.value;const body=modal.value==='service'?{...service.value,parameters:JSON.parse(parameters.value)}:{...worker.value,dataIntervalSeconds:pauseValue(worker.value.dataIntervalSeconds),emptyIntervalSeconds:pauseValue(worker.value.emptyIntervalSeconds),mark:previous&&worker.value.mark===previous.mark?undefined:worker.value.mark,pass:editId.value&&worker.value.pass===''?undefined:worker.value.pass};await api(`/${modal.value==='service'?'services':'workers'}${editId.value?'/'+editId.value:''}`,editId.value?'PUT':'POST',body);modal.value='';await refresh();});}
async function remove(kind:string,id:number){if(!confirm('Usunąć wpis? Usunięcie workera usuwa jego historię i bieżące dane pojazdów.'))return;await action(async()=>{await api(`/${kind}/${id}`,'DELETE');await refresh();});}
async function run(id:number){await action(async()=>{await api(`/workers/${id}/run`,'POST');await refresh();});}
</script>

<template>
 <main v-if="!logged" class="login"><div class="brand">T<span> / CONNECT</span></div><h1>Centrum integracji</h1><p>Zaloguj się tokenem administratora, aby zarządzać pobieraniem danych Trimble.</p><form @submit.prevent="login"><label>Token administratora<input v-model="token" type="password" required autocomplete="current-password"></label><button :disabled="busy">Otwórz panel →</button></form><p class="error" v-if="error">{{error}}</p></main>
 <div v-else class="shell">
 <aside><div class="brand">T<span> / CONNECT</span></div><small>TRIMBLE INTEGRATION</small><nav><button v-for="t in ['Przegląd','Workery','Usługi','Pojazdy','Historia']" :class="{selected:tab===t}" @click="tab=t">{{t}}</button></nav><div class="aside-bottom"><span class="dot"></span> REST API połączone<br><small>Odświeżanie co 3 sekundy</small><button class="quiet" @click="logged=false;token=''">Wyloguj się</button></div></aside>
 <section class="workspace"><header><div><small>OBSZAR ROBOCZY / {{tab.toUpperCase()}}</small><h1>{{tab==='Przegląd'?'Centrum integracji':tab}}</h1><p>Zarządzaj usługami i przepływem danych z Trimble.</p></div><button :disabled="busy" :class="status.enabled?'secondary':''" @click="action(async()=>{await api('/control','PUT',{enabled:!status.enabled});await refresh()})">{{status.enabled?'Wstrzymaj pobieranie':'Wznów pobieranie'}}</button></header>
 <div class="error" v-if="error" role="alert">{{error}} <button class="quiet" @click="error=''">Zamknij</button></div>
 <div class="notice" v-if="!status.enabled">Harmonogram wstrzymany. Rozpoczęte pobrania zostaną dokończone.</div>
 <div v-if="tab==='Przegląd'" class="stats"><article><small>PULA WORKERÓW</small><strong>{{status.capacity}}</strong><span>Niezależne wątki robocze</span></article><article><small>W TRAKCIE POBIERANIA</small><strong>{{status.running}}<em> / {{status.capacity}}</em></strong><span>{{status.enabled?'Harmonogram aktywny':'Harmonogram wstrzymany'}}</span></article><article><small>AKTYWNE KONTA</small><strong>{{status.workers.filter(w=>w.active).length}}</strong><span>{{status.workers.length}} skonfigurowanych workerów</span></article><article><small>WYMAGAJĄ UWAGI</small><strong :class="{'red':status.workers.some(w=>w.failures)}">{{status.workers.filter(w=>w.failures).length}}</strong><span>Workery z błędami</span></article></div>
 <WorkerProgress v-if="tab==='Przegląd'||tab==='Workery'" :workers="status.workers" :services="status.services" :enabled="status.enabled" />
 <section class="card" v-if="tab==='Przegląd'"><div class="card-head"><div><h2>Workery pobierania</h2><p>Każde konto ma własny harmonogram i historię.</p></div><button @click="openWorker()" :disabled="!status.services.length">+ Dodaj worker</button></div><div class="empty" v-if="!status.workers.length"><h3>Zacznij od pierwszego połączenia</h3><p>Dodaj usługę SOAP lub demo, a następnie worker z identyfikatorem klienta.</p><button class="secondary" @click="openService()">Dodaj usługę</button></div><div class="table-wrap" v-else><table><thead><tr><th>Worker / klient</th><th>Usługa / użytkownik</th><th>Status</th><th>Ostatni sukces</th><th>Akcje</th></tr></thead><tbody><tr v-for="w in status.workers" :key="w.id"><td><b>{{w.name}}</b><small>#{{w.id}} · {{w.idclient}}</small></td><td>{{serviceName(w.serviceId)}}<small>{{w.user||'Bez użytkownika'}}</small></td><td><span class="badge" :class="w.status==='error'?'bad':w.status==='running'?'blue':''">{{w.status==='running'?'Pobieranie':!w.active?'Wyłączony':!status.enabled||!status.services.find(s=>s.id===w.serviceId)?.active?'Wstrzymany':w.status==='error'?'Błąd':'Oczekuje'}}</span><small v-if="w.error" class="red">{{w.error}}</small></td><td>{{date(w.lastSuccess)}}<small v-if="w.active && w.nextRun && w.status!=='running'">Następne: {{date(w.nextRun)}}</small><small v-if="w.mark" :title="w.mark" class="cursor">mark: {{w.mark}}</small></td><td class="actions"><button class="quiet" :disabled="busy||w.status==='running'" @click="run(w.id)">Pobierz</button><button class="quiet" :disabled="w.status==='running'" @click="openWorker(w)">Edytuj</button><button class="quiet red" :disabled="w.status==='running'" @click="remove('workers',w.id)">Usuń</button></td></tr></tbody></table></div></section>
 <section class="card" v-if="tab==='Usługi'"><div class="card-head"><div><h2>Usługi SOAP</h2><p>Połączenia, operacje i częstotliwość pobierania.</p></div><button @click="openService()">+ Dodaj usługę</button></div><div class="empty" v-if="!status.services.length">Brak usług. Dodaj pierwsze połączenie.</div><div class="service-grid"><article v-for="s in status.services" :key="s.id"><span class="badge">{{s.mode.toUpperCase()}} · {{s.active?'Aktywna':'Wyłączona'}}</span><h3>{{s.name}}</h3><p>{{s.mode==='trimble'?'pollTraces · HTTP Basic':s.operation||'Przykładowe dane pojazdu'}}</p><p>{{s.mode==='trimble'?'Dane: '+s.dataIntervalSeconds+' s / brak danych: '+s.emptyIntervalSeconds+' s':'Co '+s.intervalSeconds+' s'}} · limit {{s.timeoutSeconds}} s</p><button class="quiet" @click="openService(s)">Konfiguruj</button><button class="quiet red" @click="remove('services',s.id)">Usuń</button></article></div></section>
 <section class="card" v-if="tab==='Historia'||tab==='Przegląd'"><div class="card-head"><div><h2>Ostatnie pobrania</h2><p>Do 100 ostatnich wyników na worker. Widok: 50 najnowszych.</p></div><span class="badge">NA ŻYWO</span></div><div class="empty" v-if="!runs.length">Wyniki pojawią się po pierwszym pobraniu.</div><div class="table-wrap" v-else><table><thead><tr><th>Worker</th><th>Czas</th><th>Wynik</th><th>Czas trwania</th><th></th></tr></thead><tbody><tr v-for="r in runs" :key="r.id"><td>{{status.workers.find(w=>w.id===r.workerId)?.name??r.workerId}}</td><td>{{date(r.finished)}}</td><td><span class="badge" :class="r.success?'':'bad'">{{r.success?'Sukces':'Błąd'}}</span></td><td>{{r.finished-r.started}} ms</td><td><button class="quiet" @click="action(async()=>{payload=JSON.stringify(await api('/runs/'+r.id),null,2);modal='payload'})">Zobacz wynik ↗</button></td></tr></tbody></table></div></section>
 <WorkersPanel v-if="tab==='Workery'" :workers="status.workers" :services="status.services" :enabled="status.enabled" :busy="busy" :api="api" @create="openWorker()" @create-service="openService()" @edit="openWorker" @remove="id=>remove('workers',id)" @run="run" @refresh="action(refresh)" />
 <Vehicles v-if="tab==='Pojazdy'" :api="api" :workers="status.workers" />
 <footer>Trimble Connect · Panel integracji <span>REST API · Node.js · {{Math.floor(status.uptime/60)}} min pracy</span></footer>
 </section></div>
 <div class="overlay" v-if="modal"><section class="dialog" role="dialog" aria-modal="true" aria-label="Konfiguracja"><div class="card-head"><h2>{{modal==='payload'?'Wynik pobrania':(editId?'Edytuj':'Dodaj')+(modal==='service'?' usługę':' worker')}}</h2><button type="button" class="quiet" :disabled="busy" @click="modal=''">Zamknij ✕</button></div><pre v-if="modal==='payload'">{{payload}}</pre><form v-else @submit.prevent="save"><template v-if="modal==='service'"><label>Nazwa usługi<input v-model="service.name" required maxlength="100"></label><div class="form-row"><label>Tryb<select v-model="service.mode"><option value="demo">Demo</option><option value="trimble">Trimble Tracking · pollTraces</option><option value="soap">SOAP (własna konfiguracja)</option></select></label><label v-if="service.mode!=='trimble'">Uwierzytelnianie<select v-model="service.auth"><option value="parameters">Parametry żądania</option><option value="basic">HTTP Basic</option><option value="wssecurity">WS-Security</option></select></label></div><template v-if="service.mode==='trimble'"><label>Adres usługi Tracking<input v-model="service.endpoint" type="url" required></label><p class="hint">pollTraces pobiera customer z idclient. Login i hasło są wysyłane przez HTTP Basic. Znacznik mark jest zapisywany oddzielnie dla każdego workera; Odpowiedź z danymi: pauza szybka {{service.dataIntervalSeconds}} s; bez danych: pauza długa {{service.emptyIntervalSeconds}} s. Dotyczy także kolejnych stron.</p></template><div v-if="service.mode==='trimble'" class="form-row"><label>Pauza szybka (sekundy)<input v-model.number="service.dataIntervalSeconds" type="number" min="1" max="86400" required></label><label>Pauza długa (sekundy)<input v-model.number="service.emptyIntervalSeconds" type="number" min="1" max="86400" required></label></div><template v-if="service.mode==='soap'"><label>Adres WSDL<input v-model="service.wsdl" type="url" required placeholder="https://…?wsdl"></label><label>Nazwa operacji<input v-model="service.operation" required></label></template><div class="form-row"><label>{{service.mode==='trimble'?'Bazowy interwał po błędzie (sekundy)':'Interwał (sekundy)'}}<input v-model.number="service.intervalSeconds" type="number" min="10" max="86400" required></label><label>Limit czasu (sekundy)<input v-model.number="service.timeoutSeconds" type="number" min="5" max="300" required></label></div><label v-if="service.mode!=='trimble'">Parametry SOAP (JSON)<textarea v-model="parameters" rows="7" spellcheck="false"></textarea></label><p v-if="service.mode!=='trimble'" class="hint" v-pre>Wartości {{idclient}}, {{user}}, {{pass}} zostaną pobrane z konta workera. Nie wpisuj haseł bezpośrednio w JSON.</p><label class="check"><input v-model="service.active" type="checkbox">Aktywna usługa</label></template><template v-else><label>Nazwa workera<input v-model="worker.name" required maxlength="100"></label><label>Identyfikator klienta (idclient)<input v-model="worker.idclient" required></label><label>Użytkownik<input v-model="worker.user" autocomplete="off"></label><label>Hasło<input v-model="worker.pass" type="password" autocomplete="new-password" :placeholder="editId?'Puste pole zachowa obecne hasło':''"></label><label>Usługa<select v-model.number="worker.serviceId" required><option v-for="s in status.services" :value="s.id">{{s.name}}</option></select></label><div v-if="status.services.find(s=>s.id===worker.serviceId)?.mode==='trimble'" class="form-row"><label>Pauza szybka (sekundy)<input v-model.number="worker.dataIntervalSeconds" type="number" min="1" max="86400" :placeholder="'Z usługi: '+(status.services.find(s=>s.id===worker.serviceId)?.dataIntervalSeconds??3)"></label><label>Pauza długa (sekundy)<input v-model.number="worker.emptyIntervalSeconds" type="number" min="1" max="86400" :placeholder="'Z usługi: '+(status.services.find(s=>s.id===worker.serviceId)?.emptyIntervalSeconds??180)"></label><p class="hint">Pauza szybka: są dane. Pauza długa: brak danych. Puste pole korzysta z ustawienia usługi.</p></div><label>Znacznik mark (Trimble)<input v-model="worker.mark" maxlength="4096" placeholder="Puste = 24 godziny wstecz (UTC)"></label><p class="hint">Zmiana mark pozwala ponownie pobrać dane. Zmiana klienta lub usługi resetuje poprzedni znacznik. Brak zmiany zachowuje bieżący postęp.</p><label class="check"><input v-model="worker.active" type="checkbox">Worker aktywny</label></template><p class="error" v-if="error">{{error}}</p><button :disabled="busy">{{busy?'Zapisywanie…':'Zapisz konfigurację'}}</button></form></section></div>
</template>
